import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

// ── helpers ──

const productA: Product = { id: "a", name: "Alpha", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Beta", unitPriceCents: 2000, weightGrams: 500 };

function makeDiscountPolicy(fn: (s: number) => number): DiscountPolicy {
  return { computeDiscountCents: vi.fn(fn) };
}

function makeTaxCalc(fn: (t: number, r: string) => number): TaxCalculator {
  return { computeTaxCents: vi.fn(fn) };
}

function makeShippingCalc(fn: (l: readonly CartLine[], s: number) => number): ShippingCalculator {
  return { computeShippingCents: vi.fn(fn) };
}

// ── Cart line management ──

describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("adds a product and counts items", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks different products separately", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects zero quantity on add", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
  });

  it("rejects negative quantity on add", () => {
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("rejects negative unit price on add", () => {
    const badProduct: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity of an existing product", () => {
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("removes product when quantity updated to 0", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    // Product should be gone
    expect(cart.remove("a")).toBe(false);
  });

  it("throws when updating quantity of absent product", () => {
    expect(() => cart.updateQuantity("missing", 5)).toThrow(
      "Product missing is not in the cart",
    );
  });

  it("throws on negative quantity in updateQuantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("throws on non-integer quantity in updateQuantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clears all items", () => {
    cart.add(productA, 2);
    cart.add(productB, 3);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    cart.add(productA, 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);

    // Mutating snapshot does not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

// ── Pricing pipeline ──

describe("Cart pricing pipeline", () => {
  it("computes subtotal as sum of unitPriceCents * quantity", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 3); // 6000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(8000);
  });

  it("applies discount, then tax on discounted subtotal, then shipping", () => {
    const discount = makeDiscountPolicy(() => 200);
    const tax = makeTaxCalc((t) => Math.floor(t * 0.1));
    const shipping = makeShippingCalc(() => 500);

    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(productA, 1); // subtotal 1000

    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(1000);
    expect(totals.discountCents).toBe(200);
    // Tax on discounted: (1000 - 200) * 0.1 = 80
    expect(totals.taxCents).toBe(80);
    expect(totals.shippingCents).toBe(500);
    // total = 800 + 80 + 500 = 1380
    expect(totals.totalCents).toBe(1380);
  });

  it("clamps discount to [0, subtotal] — negative discount becomes 0", () => {
    const discount = makeDiscountPolicy(() => -100);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("clamps discount to [0, subtotal] — over-subtotal capped", () => {
    const discount = makeDiscountPolicy(() => 9999);
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1); // subtotal 1000
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative tax to 0", () => {
    const tax = makeTaxCalc(() => -50);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("clamps negative shipping to 0", () => {
    const shipping = makeShippingCalc(() => -100);
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(productA, 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("passes region to tax calculator", () => {
    const tax = makeTaxCalc((_t, _r) => 0);
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "FR");
  });

  it("defaults region to US", () => {
    const tax = makeTaxCalc((_t, _r) => 0);
    const cart = new Cart({ taxCalculator: tax });
    cart.add(productA, 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(expect.any(Number), "US");
  });

  it("empty cart produces zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("uses defaults (no discount, no tax, free shipping) when no config", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(1000);
  });
});

