describe("Cart.checkout()", () => {
  it("returns totals and lines for simple checkout without collaborators", async () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(2000);
    expect(result.lines).toHaveLength(1);
    expect(result.lines[0]!.quantity).toBe(2);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(productA, 1); // original price 1000

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };

    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(1500);
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledWith("a");
  });

  it("propagates priceFetcher failure", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };

    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service down",
    );
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "out of stock" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("out of stock");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(productA, 10);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("passes inventory check when available and quantity sufficient", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 5 }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes inventory check when availableQuantity is undefined", async () => {
    const cart = new Cart();
    cart.add(productA, 2);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };

    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discount = makeDiscountPolicy(() => 100);
    const shipping = makeShippingCalc(() => 200);
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(productA, 1); // subtotal 1000

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };

    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal 1000, discount 100 → discounted 900, tax 900*0.1=90, shipping 200
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(100);
    expect(result.totals.taxCents).toBe(90);
    expect(result.totals.shippingCents).toBe(200);
    expect(result.totals.totalCents).toBe(900 + 90 + 200);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates async tax provider failure", async () => {
    const cart = new Cart();
    cart.add(productA, 1);

    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
    };

    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "tax service down",
    );
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const cart = new Cart({ region: "US" });
    cart.add(productA, 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500), // price drops to 500
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.05),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // subtotal = 500 * 2 = 1000, no discount → tax = 1000 * 0.05 = 50
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.taxCents).toBe(50);
    expect(priceFetcher.fetchPriceCents).toHaveBeenCalledTimes(2);
    expect(inventoryChecker.check).toHaveBeenCalledWith("a", 2);
  });

  it("generates default message on inventory denial without reason", async () => {
    const cart = new Cart();
    cart.add(productA, 5);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: false,
        availableQuantity: 2,
      }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InventoryError;
      expect(invErr.message).toContain("insufficient stock");
      expect(invErr.message).toContain("a");
      expect(invErr.available).toBe(2);
    }
  });

  it("checks inventory for first denied product only", async () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 1);

    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
        .mockResolvedValueOnce({ available: false, reason: "gone" })
        .mockResolvedValueOnce({ available: true }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      // Second product should not have been checked since first failed
      expect(inventoryChecker.check).toHaveBeenCalledTimes(1);
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 50000])("returns 0 regardless of subtotal (%i)", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity])(
      "rejects out-of-range percent (%s)",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent (%i)", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  it("computes 10% of 10000 as 1000", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down fractional cents (33% of 100 = 33)", () => {
    const policy = new PercentageDiscountPolicy(33);
    expect(policy.computeDiscountCents(100)).toBe(33);
  });

  it("rounds down to nearest cent (15% of 999)", () => {
    const policy = new PercentageDiscountPolicy(15);
    // 999 * 15 / 100 = 149.85 → floor → 149
    expect(policy.computeDiscountCents(999)).toBe(149);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });

  it("100% returns the full subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(7777)).toBe(7777);
  });

  it("0% returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps discount at subtotal when fixed exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(2000);
    expect(policy.computeDiscountCents(500)).toBe(500);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("returns exact subtotal when fixed equals subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(1000);
    expect(policy.computeDiscountCents(1000)).toBe(1000);
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent discounts from original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child discounts to 0 before summing", () => {
      const negPolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negPolicy, new FixedAmountDiscountPolicy(50)],
        "sum",
      );
      // max(0, -100) + max(0, 50) = 50
      expect(composite.computeDiscountCents(1000)).toBe(50);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when mode omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100 → remaining 900
      // Second: 10% of 900 = 90 → total discount = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // Fixed 200 from 1000 → remaining 800, then 10% of 800 = 80 → total 280
      expect(composite1.computeDiscountCents(1000)).toBe(280);

      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // 10% of 1000 = 100 → remaining 900, then fixed 200 → total 300
      expect(composite2.computeDiscountCents(1000)).toBe(300);
    });

    it("stops reducing once remaining is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new FixedAmountDiscountPolicy(600)],
        "chain",
      );
      // Fixed 500 from 500 → remaining 0, second yields 0 → total 500
      expect(composite.computeDiscountCents(500)).toBe(500);
    });

    it("clamps negative child discounts to 0 in chain mode", () => {
      const negPolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negPolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // max(0, -50) = 0, remaining still 1000, then fixed 100 → total 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 for zero subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

