  });
});

describe("WeightBasedShippingCalculator", () => {
  const brackets = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket is required",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () => new WeightBasedShippingCalculator([{ upToGrams: -1, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: -1 }]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([{ upToGrams: 500, costCents: 1.5 }]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 100 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents(emptyLines, 1000)).toBe(0);
  });

  it("returns 0 for items with no weight", () => {
    const line: CartLine = {
      product: { id: "x", name: "X", unitPriceCents: 100 },
      quantity: 3,
    };
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([line], 1000)).toBe(0);
  });

  it("selects first bracket when weight is within it", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
  });

  it("selects bracket at boundary (exactly upToGrams)", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([makeLine("a", 500)], 1000)).toBe(300);
  });

  it("selects next bracket when weight exceeds first boundary", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([makeLine("a", 501)], 1000)).toBe(600);
  });

  it("selects heaviest bracket at its boundary", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([makeLine("a", 5000)], 1000)).toBe(1200);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(brackets, 2500);
    expect(calc.computeShippingCents([makeLine("a", 6000)], 1000)).toBe(2500);
  });

  it("falls back to heaviest bracket cost when no overflow defined", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    expect(calc.computeShippingCents([makeLine("a", 9999)], 1000)).toBe(1200);
  });

  it("sums weight across multiple lines and quantities", () => {
    const calc = new WeightBasedShippingCalculator(brackets);
    // 200*2 + 300*1 = 700 → second bracket (501-1000 → 600)
    const lines = [makeLine("a", 200, 2), makeLine("b", 300, 1)];
    expect(calc.computeShippingCents(lines, 1000)).toBe(600);
  });

  it("sorts brackets internally regardless of input order", () => {
    const unordered = [
      { upToGrams: 5000, costCents: 1200 },
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 1000, costCents: 600 },
    ];
    const calc = new WeightBasedShippingCalculator(unordered);
    expect(calc.computeShippingCents([makeLine("a", 400)], 1000)).toBe(300);
  });
});

import { describe, it, expect, vi } from "vitest";
import {
  InventoryError,
  refreshPrices,
  type PriceFetcher,
} from "../src/inventory.ts";
import type { CartLine } from "../src/product.ts";

describe("InventoryError", () => {
