import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 50000])("returns 0 regardless of subtotal (%i)", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity])(
      "rejects out-of-range percent (%s)",
      (pct) => {
        expect(() => new PercentageDiscountPolicy(pct)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent (%i)", (pct) => {
      expect(() => new PercentageDiscountPolicy(pct)).not.toThrow();
    });
  });

  it("computes 10% of 10000 as 1000", () => {
    const policy = new PercentageDiscountPolicy(10);
    expect(policy.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down fractional cents (33% of 100 = 33)", () => {
    const policy = new PercentageDiscountPolicy(33);
    expect(policy.computeDiscountCents(100)).toBe(33);
  });

  it("rounds down to nearest cent (15% of 999)", () => {
    const policy = new PercentageDiscountPolicy(15);
    // 999 * 15 / 100 = 149.85 → floor → 149
    expect(policy.computeDiscountCents(999)).toBe(149);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new PercentageDiscountPolicy(50);
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });

  it("100% returns the full subtotal", () => {
    const policy = new PercentageDiscountPolicy(100);
    expect(policy.computeDiscountCents(7777)).toBe(7777);
  });

  it("0% returns 0", () => {
    const policy = new PercentageDiscountPolicy(0);
    expect(policy.computeDiscountCents(5000)).toBe(0);
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts zero", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(1000)).toBe(500);
  });

  it("caps discount at subtotal when fixed exceeds subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(2000);
    expect(policy.computeDiscountCents(500)).toBe(500);
  });

  it("returns 0 for zero subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(500);
    expect(policy.computeDiscountCents(-100)).toBe(0);
  });

  it("returns exact subtotal when fixed equals subtotal", () => {
    const policy = new FixedAmountDiscountPolicy(1000);
    expect(policy.computeDiscountCents(1000)).toBe(1000);
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums independent discounts from original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 1000 = 100, fixed 200 → sum = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("clamps negative child discounts to 0 before summing", () => {
      const negPolicy = { computeDiscountCents: () => -100 };
      const composite = new CompositeDiscountPolicy(
        [negPolicy, new FixedAmountDiscountPolicy(50)],
        "sum",
      );
      // max(0, -100) + max(0, 50) = 50
      expect(composite.computeDiscountCents(1000)).toBe(50);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("defaults to sum mode when mode omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new PercentageDiscountPolicy(10),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // First: 10% of 1000 = 100 → remaining 900
      // Second: 10% of 900 = 90 → total discount = 190
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("ordering matters in chain mode", () => {
      const composite1 = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // Fixed 200 from 1000 → remaining 800, then 10% of 800 = 80 → total 280
      expect(composite1.computeDiscountCents(1000)).toBe(280);

      const composite2 = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      // 10% of 1000 = 100 → remaining 900, then fixed 200 → total 300
      expect(composite2.computeDiscountCents(1000)).toBe(300);
    });

    it("stops reducing once remaining is 0", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(500), new FixedAmountDiscountPolicy(600)],
        "chain",
      );
      // Fixed 500 from 500 → remaining 0, second yields 0 → total 500
      expect(composite.computeDiscountCents(500)).toBe(500);
    });

    it("clamps negative child discounts to 0 in chain mode", () => {
      const negPolicy = { computeDiscountCents: () => -50 };
      const composite = new CompositeDiscountPolicy(
        [negPolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // max(0, -50) = 0, remaining still 1000, then fixed 100 → total 100
      expect(composite.computeDiscountCents(1000)).toBe(100);
    });

    it("returns 0 for zero subtotal in chain mode", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

