import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart } from "../src/cart.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product, CartLine } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

// ── helpers ──

const productA: Product = { id: "a", name: "Alpha", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Beta", unitPriceCents: 2000, weightGrams: 500 };

function makeDiscountPolicy(fn: (s: number) => number): DiscountPolicy {
  return { computeDiscountCents: vi.fn(fn) };
}

function makeTaxCalc(fn: (t: number, r: string) => number): TaxCalculator {
  return { computeTaxCents: vi.fn(fn) };
}

function makeShippingCalc(fn: (l: readonly CartLine[], s: number) => number): ShippingCalculator {
  return { computeShippingCents: vi.fn(fn) };
}

// ── Cart line management ──

describe("Cart line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("adds a product and counts items", () => {
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(3);
  });

  it("merges quantities when adding same product twice", () => {
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks different products separately", () => {
    cart.add(productA, 1);
    cart.add(productB, 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-integer quantity on add", () => {
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("rejects zero quantity on add", () => {
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
  });

  it("rejects negative quantity on add", () => {
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("rejects negative unit price on add", () => {
    const badProduct: Product = { id: "bad", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(badProduct, 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updates quantity of an existing product", () => {
    cart.add(productA, 5);
    cart.updateQuantity("a", 2);
    expect(cart.itemCount).toBe(2);
  });

  it("removes product when quantity updated to 0", () => {
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    // Product should be gone
    expect(cart.remove("a")).toBe(false);
  });

  it("throws when updating quantity of absent product", () => {
    expect(() => cart.updateQuantity("missing", 5)).toThrow(
      "Product missing is not in the cart",
    );
  });

  it("throws on negative quantity in updateQuantity", () => {
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("throws on non-integer quantity in updateQuantity", () => {
    cart.add(productA, 1);
